import { expect, test, uniqueName } from "../../fixtures";

// features/vendors.feature: Reject invalid vendor fields
const cases: Array<[string, unknown]> = [
  ["name", "A"],
  ["category", "furniture"],
  ["contact_email", "not-an-email"],
];

for (const [field, value] of cases) {
  test(`rejects invalid ${field} with validation_error naming the field`, { tag: "@VEN-02" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const body: Record<string, unknown> = {
      name: uniqueName("Acme Freight"),
      category: "logistics",
      contact_email: "ops@acme.example",
    };
    body[field] = value;

    // Act
    const res = await member.post("/api/vendors", { data: body });
    const text = await res.text();

    // Assert
    expect(res.status(), text).toBe(422);
    const error = JSON.parse(text).error;
    expect(error.code, text).toBe("validation_error");
    const fields = (error.fields ?? []).map((f: { field: string }) => f.field);
    expect(fields, text).toContain(field);
  });
}
